; Tab2D_4127 ($4127): 2D table, 2 points, unsigned
; Inputs: ManifoldVacuum
; Read at $13B26
;---------------------------------------------------------------------------------------------------
Tab2D_4127:
        dc.b    2,$80                                    ; points, flags
        dc.b    8,91, 154,0                              ; x, y

        dc.b    $FF,$FF,$FF,$FF,$02,$00
MapCheckBaroMax:
        dc.b    $E3                                      ; MAP checks: barometric pressure above which the high-altitude vacuum limit is not used
MapCheckVacuumMin:
        dc.b    $07                                      ; MAP checks: manifold vacuum limit (low altitude)
MapCheckVacuumMinAlt:
        dc.b    $03                                      ; MAP checks: manifold vacuum limit (high altitude)
MapRawLowLimit:
        dc.b    $02                                      ; Raw MAP below this value is a low input (P0107; ReadMap, MapCircuitCheck, MapKeyOnCheck)
MapRawHighLimit:
        dc.b    $FD                                      ; Raw MAP at or above this value is a high input (P0108; ReadMap, MapCircuitCheck)
        dc.b    $18,$1C,$70
MapRationalThrottleMax:
        dc.b    $3D                                      ; MAP rationality (MapCircuitCheck, ReadMap): throttle opening below this value for the rpm/MAP check
MapLimpOffset:
        dc.b    $20                                      ; Limp-home MAP from throttle (LimpMapCalc): offset added to MapLimpFromThrottle
MapLimpThrottleOffset:
        dc.b    $09                                      ; Limp-home MAP from throttle: offset added to the throttle reading

;---------------------------------------------------------------------------------------------------
; MapLimpFromThrottle ($413E): 2D table, 5 points, unsigned
; Substitute MAP from the throttle position when the MAP sensor has failed
; x: raw, y: kpa (units: docs/en/calibration.md)
; Inputs: ?; Throttle
; Read at $19C4C
;---------------------------------------------------------------------------------------------------
MapLimpFromThrottle:
        dc.b    5,$80                                    ; points, flags
        dc.b    0,22, 8,91, 20,129, 57,199, 120,206      ; x, y

AcSensorRawHigh:
        dc.b    $FB                                      ; A/C sensor circuit check: raw value above this counts as open/high
AcSensorRawLow:
        dc.b    $03                                      ; A/C sensor circuit check: raw value below this counts as shorted/low
AcSensorFaultValue:
        dc.b    $E0                                      ; A/C sensor value used with a sensor fault
CoolantRawLow:
        dc.b    $1A                                      ; Coolant sensor raw value below which it counts as shorted (fault)
CoolantRawHigh:
        dc.b    $FD                                      ; Coolant sensor raw value at or above which it counts as open (fault)
CoolantFaultValue:
        dc.b    $AE                                      ; Coolant value used with a coolant sensor fault
        dc.b    $79,$E4,$C7,$FF
AirTempRawLow:
        dc.b    $1A                                      ; Air temperature sensor raw value below which it counts as shorted
AirTempRawHigh:
        dc.b    $FD                                      ; Air temperature sensor raw value at or above which it counts as open
AirTempFaultValue:
        dc.b    $AE                                      ; Air temperature used with a sensor fault (otherwise coolant is used)
BatteryTempRawLow:
        dc.b    $05                                      ; Battery temperature sensor raw value below which it counts as shorted
BatteryTempRawHigh:
        dc.b    $FA                                      ; Battery temperature sensor raw value above which it counts as open
        dc.b    $33,$B6

